import React, { useState } from "react";
import ReactPlayer from "react-player";
import song from "../assets/game_bg_music.mp3";
import { VolumeOffOutlined, VolumeUpOutlined } from "@mui/icons-material";
import { Button } from "@mui/material";
import soundOff from "../Images/soundOff.png";
import soundOn from "../Images/soundOn.png";
import { useTranslation } from "react-i18next";

function AudioPlayer() {
  const { t, i18n } = useTranslation();
  const [isMuted, setIsMuted] = useState(false);

  const toggleMute = () => {
    setIsMuted((prevIsMuted) => !prevIsMuted);
  };

  return (
    <div
      className=" d-flex justify-content-center align-items-center"
      style={{ cursor: "pointer" }}
    >
      <ReactPlayer
        url={song}
        loop={true}
        playing={!isMuted}
        muted={false}
        width="10px"
        height="10px"
        volume="0.3"
      />

      {/* {isMuted ? (
          <img
          src={soundOff}
          onClick={toggleMute}
          className="rounded-5"
          variant="contained"
          color="secondary"
          size="small"
          style={{ height:"34px",marginTop:"5px"}}          
          title="unmute"
        ></img>
        
      ) : (
        <img
        src={soundOn}
        onClick={toggleMute}
        className="rounded-5"
        variant="contained"
        color="secondary"
        size="small"
        style={{height:"35px",marginTop:"5px"}}
        title="mute"
      ></img>
    
      )}  */}

      {isMuted ? (
        <img
          src={soundOff}
          onClick={toggleMute}
          className="rounded-5"
          variant="contained"
          color="secondary"
          size="small"
          title={t("unmute")}
        ></img>
      ) : (
        <img
          src={soundOn}
          onClick={toggleMute}
          className="rounded-5"
          variant="contained"
          color="secondary"
          size="small"
          title={t("mute")}
        ></img>
      )}
    </div>
  );
}

export default AudioPlayer;
