import { Theory, TheoryPageWithLabel } from "english-olabsnxtg-library";
import React from "react";
import QuizPopupContent from "./QuizPopupContent";
import Theorytext from "./Theorytext";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";

const TheoryPage = () => {
  const { t, i18n } = useTranslation();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  return (
    <TheoryPageWithLabel
      H_title={t("title")}
      H_sidebarvisible="visible"
      HQ_quittext={t("want_to_quit")}
      HQ_yes={t("yes")}
      HQ_cancel={t("cancel")}
      RSM_QuizPopupContent_comp={<QuizPopupContent />}
      RSM_Intruc_popup_title_string={t("quiz_instruction")}
      RSM_ok={t("ok")}
      RSM_theory_tt={t("theory")}
      RSM_vivavoce_tt={t("viva_voce")}
      RSM_help_tt={t("help")}
      RSM_procedure_tt={t("procedure")}
      RSM_animation_tt={t("animation")}
      M_workbenchLebel_landscape={t("theory_landscape")}
      M_workbenchLebel_portrait={t("theory_potrait")}
      M_midheight="90%"
      M_midcontent_comp={<Theorytext />}
      WS_sendJsonMessage={sendJsonMessage}
      WS_SendLogData={SendLogData}
      labNo="CDAC-OlabsNxtG-En-21"
      labShortName="Transitive and Intransitive Verb"
    />
  );
};

export default TheoryPage;
